param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$taskCore=Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict'
$taskPolicy=[IO.File]::ReadAllText((Join-Path $taskCore 'Orders/AICF_PlayerMobHoldPolicy.c'))
$taskController=[IO.File]::ReadAllText((Join-Path $taskCore 'Bootstrap/AICF_MatchController.c'))
$taskArrival=[IO.File]::ReadAllText((Join-Path $taskCore 'Orders/AICF_DefendArrivalHandoff.c'))
function Body([string]$Source,[string]$Name){Get-AICFMethodBody ([pscustomobject]@{Source=$Source;Code=(ConvertTo-AICFCodeText $Source)}) $Name}
function HashText([string]$Text){$h=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text.Replace("`r`n","`n")))).Replace('-','')}finally{$h.Dispose()}}
if((HashText (Body $taskPolicy 'IsReachedCurrentHold')) -ne '453FB4290B73FFF8973645BE769AB5E6B0CFD1774F0F263C7F66ECC3C55CD289'){throw 'Original all-member arrival predicate changed'}
$taskAudit=Body $taskController 'AuditActiveFactionTasking'
$taskFlow=[regex]::Match($taskAudit,'bool internalTask = AICF_PlayerMobHoldPolicy\.HasCurrentInternalTask\(slot, mainBase, STUCK_WATCHDOG_IGNORE_RADIUS_METERS\);\s*bool mobPresenceRequiresEgress = [^;]+;').Value
if(!$taskFlow -or $taskFlow -notmatch 'atMob && !allowedException && !internalTask;'){throw 'Egress-only integration missing'}
if((Body $taskController 'ResolveAllowedIdleReason') -match 'HasCurrentInternalTask' -or (Body $taskController 'HasMeaningfulTask') -match 'HasCurrentInternalTask' -or (Body $taskController 'MonitorGroupProgress') -match 'HasCurrentInternalTask'){throw 'Internal task must not grant arrival, idle or movement progress'}
if($taskPolicy -match '\b(CallLater|Teleport|SpawnEntity|DeleteEntity|CommitTransition|ResetMob|ObserveUnexplainedMobIdle|MarkProgress|SetOrigin|AddAction)\s*\('){throw 'Policy gained side effects'}
foreach($taskRequired in @('slot.ObserveMeaningfulTaskLoss(!meaningfulTask, UPDATE_INTERVAL_MS)','mobPresenceRequiresEgress && !recentOutwardProgress','MOB_EGRESS_HARD_DEADLINE_INTERVALS * commanderIntervalMs','" internal_task=%1 egress_required=%2", internalTask, mobPresenceRequiresEgress')){if(!$taskAudit.Contains($taskRequired)){throw "Existing counter/deadline or actual audit telemetry changed: $taskRequired"}}
$taskActivity=Body $taskController 'EmitStage35FactionActivity'
if($taskActivity -notmatch 'HasCurrentInternalTask[\s\S]*TryObserveGroupMobEnvelope[\s\S]*internal_task=%1 egress_required=%2'){throw 'Periodic telemetry must independently read current task and physical envelope'}
function Replay([string]$Text){
 $Text=$Text.Replace('protected static bool','public static bool').Replace('static bool HasCurrentInternalTask','public static bool HasCurrentInternalTask').Replace('static bool IsReachedCurrentHold','public static bool IsReachedCurrentHold')
 $Text=$Text.Replace('class AICF_PlayerMobHoldPolicy','public class AICF_PlayerMobHoldPolicy')
 $Text=$Text.Replace('array<AIWaypoint> waypoints = {};','EArray<AIWaypoint> waypoints = new EArray<AIWaypoint>();').Replace('array<AIAgent> agents = {};','EArray<AIAgent> agents = new EArray<AIAgent>();')
 $Text=$Text.Replace('foreach (AIAgent agent : agents)','foreach (AIAgent agent in agents)').Replace('int alive;','int alive=0;').Replace('IEntity member;','IEntity member=null;')
 $Text=$Text.Replace('FindComponent(CharacterControllerComponent)','FindComponent(typeof(CharacterControllerComponent))').Replace('FindComponent(CompartmentAccessComponent)','FindComponent(typeof(CompartmentAccessComponent))')
 $Text=$Text.Replace('activity.Type() != SCR_AIMoveActivity','activity.Type() != typeof(SCR_AIMoveActivity)').Replace('activity.Type() != SCR_AIDefendActivity','activity.Type() != typeof(SCR_AIDefendActivity)')
 return [regex]::Replace($Text,'\bEntityID\b','int')
}
$taskShim=@'
using System;using System.Collections.Generic;
namespace MobInternalReplay {
public class N{public static implicit operator bool(N n){return n!=null;}}public static class ReplayGuard{public static bool On(){return true;}public static bool Off(){return false;}}
public struct vector{public float X,Y,Z;public vector(float x,float z){X=x;Y=0;Z=z;}public static float DistanceSqXZ(vector a,vector b){return (a.X-b.X)*(a.X-b.X)+(a.Z-b.Z)*(a.Z-b.Z);}public static bool operator==(vector a,vector b){return a.X==b.X&&a.Y==b.Y&&a.Z==b.Z;}public static bool operator!=(vector a,vector b){return !(a==b);}public override bool Equals(object o){return o is vector&&(vector)o==this;}public override int GetHashCode(){return X.GetHashCode()^Y.GetHashCode()^Z.GetHashCode();}}
public class EArray<T>:List<T>{public new int Count(){return base.Count;}public bool IsEmpty(){return base.Count==0;}}
public static class Replication{public static bool Server=true;public static bool IsServer(){return Server;}}
public enum AICF_EStrategicDecisionAuthority{AI_COMMANDER,PLAYER_COMMAND}public enum AICF_EOrderTargetKind{NONE,BASE,POSITION}public enum EAIActionState{EVALUATED,RUNNING,FAILED,COMPLETED}
public class IEntity:N{public vector Position;public vector GetOrigin(){return Position;}public virtual N FindComponent(Type t){return null;}}
public class AIWaypoint:IEntity{public float Radius=20;public float GetCompletionRadius(){return Radius;}}
public class SCR_DefendWaypoint:AIWaypoint{public static SCR_DefendWaypoint Cast(AIWaypoint w){return w as SCR_DefendWaypoint;}}
public class AIActionBase:N{public EAIActionState State=EAIActionState.RUNNING;public bool Suspended,Remove;public Type Type(){return GetType();}public EAIActionState GetActionState(){return State;}public bool GetActionIsSuspended(){return Suspended;}public bool GetRemoveAction(){return Remove;}}
public class SCR_AIActivityBase:AIActionBase{public AIWaypoint m_RelatedWaypoint;public static SCR_AIActivityBase Cast(AIActionBase a){return a as SCR_AIActivityBase;}}
public class SCR_AIMoveActivity:SCR_AIActivityBase{}public class SCR_AIDefendActivity:SCR_AIActivityBase{}public class ForeignMove:SCR_AIMoveActivity{}
public class SCR_AIGroupUtilityComponent:N{public AIActionBase Current,Executed;public AIActionBase GetCurrentAction(){return Current;}public AIActionBase GetExecutedAction(){return Executed;}}
public class SCR_AIGroup:IEntity{public int Id=1;public SCR_AIGroupUtilityComponent Utility=new SCR_AIGroupUtilityComponent();public AIWaypoint CurrentWaypoint;public EArray<AIWaypoint> Waypoints=new EArray<AIWaypoint>();public EArray<AIAgent> Agents=new EArray<AIAgent>();public Action OnWaypoints,OnAgents;public int GetID(){return Id;}public AIWaypoint GetCurrentWaypoint(){return CurrentWaypoint;}public SCR_AIGroupUtilityComponent GetGroupUtilityComponent(){return Utility;}public void GetWaypoints(EArray<AIWaypoint> a){a.AddRange(Waypoints);if(OnWaypoints!=null)OnWaypoints();}public void GetAgents(EArray<AIAgent> a){a.AddRange(Agents);if(OnAgents!=null)OnAgents();}}
public class AIAgent:N{public IEntity Actor;public SCR_AIGroup Group;public IEntity GetControlledEntity(){return Actor;}public SCR_AIGroup GetParentGroup(){return Group;}}
public class AIControlComponent:N{public AIAgent Agent;public AIAgent GetControlAIAgent(){return Agent;}}
public class CharacterControllerComponent:N{public static CharacterControllerComponent Cast(N n){return n as CharacterControllerComponent;}}
public class CompartmentAccessComponent:N{public bool Inside,GettingIn,GettingOut,Switching;public IEntity Attached;public bool IsInCompartment(){return Inside;}public bool IsGettingIn(){return GettingIn;}public bool IsGettingOut(){return GettingOut;}public bool IsSwitchingSeatsAnim(){return Switching;}public static CompartmentAccessComponent Cast(N n){return n as CompartmentAccessComponent;}public static IEntity GetVehicleIn(IEntity e){var c=e as ChimeraCharacter;return c==null||c.Access==null?null:c.Access.Attached;}}
public class ChimeraCharacter:IEntity{public bool Alive=true,Conscious=true,InVehicle;public AIControlComponent Control=new AIControlComponent();public CompartmentAccessComponent Access=new CompartmentAccessComponent();public CharacterControllerComponent Controller=new CharacterControllerComponent();public static ChimeraCharacter Cast(IEntity e){return e as ChimeraCharacter;}public CharacterControllerComponent GetCharacterController(){return Controller;}public AIControlComponent GetAIControlComponent(){return Control;}public CompartmentAccessComponent GetCompartmentAccessComponent(){return Access;}public bool IsInVehicle(){return InVehicle;}public override N FindComponent(Type t){return t==typeof(CharacterControllerComponent)?(N)Controller:Access;}}
public static class AICF_GroupRuntime{public static bool IsAliveCharacter(IEntity e){var c=e as ChimeraCharacter;return c!=null&&c.Alive&&c.Controller!=null;}public static IEntity ResolveAliveLeader(SCR_AIGroup g){if(g==null)return null;foreach(var a in g.Agents)if(a!=null&&IsAliveCharacter(a.Actor))return a.Actor;return null;}}
public static class SCR_AIDamageHandling{public static bool IsConscious(ChimeraCharacter c){return c.Conscious;}}
public static class AICF_Stage1Config{public const int MAX_GROUP_SIZE=10;}
public class SCR_CampaignMilitaryBaseComponent:N{public IEntity Owner=new IEntity();public IEntity GetOwner(){return Owner;}}
public class AICF_GroupSlot:N{public bool Ready=true,PlayerIntent=true,Pending,Failed,Approach;public AICF_EStrategicDecisionAuthority Authority=AICF_EStrategicDecisionAuthority.PLAYER_COMMAND;public AICF_EOrderTargetKind Kind=AICF_EOrderTargetKind.POSITION,IntentKind=AICF_EOrderTargetKind.POSITION;public string Posture="MOVE_AND_HOLD",IntentPosture="MOVE_AND_HOLD";public vector Target,IntentTarget;public SCR_AIGroup Group;public AIWaypoint Waypoint;public int Generation=1,Assignment=1,Intent=1;public bool IsCombatReady(){return Ready;}public bool HasPlayerStrategicIntent(){return PlayerIntent;}public AICF_EStrategicDecisionAuthority GetDecisionAuthority(){return Authority;}public AICF_EOrderTargetKind GetTargetKind(){return Kind;}public AICF_EOrderTargetKind GetPlayerStrategicIntentTargetKind(){return IntentKind;}public string GetStrategicIntentPosture(){return IntentPosture;}public string GetOperationalPosture(){return Posture;}public vector GetTargetPosition(){return Target;}public vector GetPlayerStrategicIntentTargetPosition(){return IntentTarget;}public bool HasPendingOrderRecovery(){return Pending;}public bool HasFailedMovement(){return Failed;}public bool IsApproachRouteWaypoint(){return Approach;}public SCR_AIGroup GetGroup(){return Group;}public AIWaypoint GetWaypoint(){return Waypoint;}public int GetSpawnGeneration(){return Generation;}public int GetStrategicAssignmentRevision(){return Assignment;}public int GetPlayerStrategicIntentRevision(){return Intent;}}
public static class AICF_DefendArrivalHandoff{public static bool IsFormationAtWaypoint(SCR_AIGroup group,AIWaypoint waypoint)FORMATION}
public static class Flow{public static bool Egress(AICF_GroupSlot slot,SCR_CampaignMilitaryBaseComponent mainBase,bool atMob,bool allowedException){const float STUCK_WATCHDOG_IGNORE_RADIUS_METERS=100;FLOW return mobPresenceRequiresEgress;}public static bool LegacyEgress(bool atMob,bool allowedException){return atMob&&!allowedException;}}
'@
$taskCases=@'
public static class Cases{
static AICF_GroupSlot S;static SCR_CampaignMilitaryBaseComponent B;static SCR_AIGroup G;static SCR_DefendWaypoint W;static SCR_AIActivityBase A;static ChimeraCharacter Leader,Tail;
static void Setup(){Replication.Server=true;B=new SCR_CampaignMilitaryBaseComponent();G=new SCR_AIGroup();W=new SCR_DefendWaypoint();A=new SCR_AIMoveActivity{m_RelatedWaypoint=W};G.Utility.Current=G.Utility.Executed=A;G.CurrentWaypoint=W;G.Waypoints.Add(W);S=new AICF_GroupSlot{Group=G,Waypoint=W};Leader=Add(16);Tail=Add(36);}
static ChimeraCharacter Add(float x){var c=new ChimeraCharacter{Position=new vector(x,0)};var a=new AIAgent{Actor=c,Group=G};c.Control.Agent=a;G.Agents.Add(a);return c;}
static bool Internal(){return AICF_PlayerMobHoldPolicy.HasCurrentInternalTask(S,B,100);}
static void Reject(string name){if(Internal())throw new Exception("unsafe internal task: "+name);if(!Flow.Egress(S,B,true,false))throw new Exception("egress incorrectly suppressed: "+name);}
public static int Run(){int n=0;Setup();if(!Internal()||AICF_PlayerMobHoldPolicy.IsReachedCurrentHold(S,B,100)||Flow.Egress(S,B,true,false)||!Flow.LegacyEgress(true,false))throw new Exception("real internal move is not arrival or outward intent");n++;
if(!Internal()||AICF_PlayerMobHoldPolicy.IsReachedCurrentHold(S,B,100))throw new Exception("serial stationary RUNNING must never prove arrival");n++;
Setup();A=new SCR_AIDefendActivity{m_RelatedWaypoint=W};G.Utility.Current=G.Utility.Executed=A;if(!Internal()||AICF_PlayerMobHoldPolicy.IsReachedCurrentHold(S,B,100))throw new Exception("internal defend task must not prove formation arrival");n++;
Setup();Tail.Position=new vector(19,0);if(!AICF_PlayerMobHoldPolicy.IsReachedCurrentHold(S,B,100)||!Internal())throw new Exception("existing all-member reached hold changed");n++;
foreach(string k in new[]{"client","notReady","slotMissing","baseMissing","ownerMissing","zeroRadius","negativeRadius","AI","noIntent","baseIntent","baseTarget","intentPosture","posture","targetMismatch","pending","failed","approach","noGroup","noWaypoint","wrongWaypointType","notCurrent","notQueued","utilityMissing","selectedForeign","executedForeign","wrongType","subclass","evaluated","failedAction","completedAction","suspended","removed","relatedForeign","targetOutside","wpOutside","wpNotAtTarget","emptyRoster","unknownAgent","unknownActor","nonCharacter","noCharacterController","wrongParent","wrongControl","noControl","noAccess","unconscious","memberVehicle","inside","gettingIn","gettingOut","switching","attached","noLiving","overflow"}){Setup();switch(k){case"client":Replication.Server=false;break;case"notReady":S.Ready=false;break;case"slotMissing":S=null;break;case"baseMissing":B=null;break;case"ownerMissing":B.Owner=null;break;case"zeroRadius":if(AICF_PlayerMobHoldPolicy.HasCurrentInternalTask(S,B,0))throw new Exception(k);n++;continue;case"negativeRadius":if(AICF_PlayerMobHoldPolicy.HasCurrentInternalTask(S,B,-1))throw new Exception(k);n++;continue;case"AI":S.Authority=AICF_EStrategicDecisionAuthority.AI_COMMANDER;break;case"noIntent":S.PlayerIntent=false;break;case"baseIntent":S.IntentKind=AICF_EOrderTargetKind.BASE;break;case"baseTarget":S.Kind=AICF_EOrderTargetKind.BASE;break;case"intentPosture":S.IntentPosture="ATTACK";break;case"posture":S.Posture="ATTACK";break;case"targetMismatch":S.IntentTarget=new vector(1,0);break;case"pending":S.Pending=true;break;case"failed":S.Failed=true;break;case"approach":S.Approach=true;break;case"noGroup":S.Group=null;break;case"noWaypoint":S.Waypoint=null;break;case"wrongWaypointType":S.Waypoint=new AIWaypoint();break;case"notCurrent":G.CurrentWaypoint=new SCR_DefendWaypoint();break;case"notQueued":G.Waypoints.Clear();break;case"utilityMissing":G.Utility=null;break;case"selectedForeign":G.Utility.Current=new AIActionBase();break;case"executedForeign":G.Utility.Executed=new SCR_AIMoveActivity();break;case"wrongType":G.Utility.Current=G.Utility.Executed=new SCR_AIActivityBase{m_RelatedWaypoint=W};break;case"subclass":G.Utility.Current=G.Utility.Executed=new ForeignMove{m_RelatedWaypoint=W};break;case"evaluated":A.State=EAIActionState.EVALUATED;break;case"failedAction":A.State=EAIActionState.FAILED;break;case"completedAction":A.State=EAIActionState.COMPLETED;break;case"suspended":A.Suspended=true;break;case"removed":A.Remove=true;break;case"relatedForeign":A.m_RelatedWaypoint=new SCR_DefendWaypoint();break;case"targetOutside":S.Target=S.IntentTarget=new vector(100.5f,0);W.Position=new vector(100,0);break;case"wpOutside":S.Target=S.IntentTarget=new vector(100,0);W.Position=new vector(100.5f,0);break;case"wpNotAtTarget":W.Position=new vector(1.1f,0);break;case"emptyRoster":G.Agents.Clear();break;case"unknownAgent":G.Agents.Add(null);break;case"unknownActor":G.Agents[1].Actor=null;break;case"nonCharacter":G.Agents[1].Actor=new IEntity();break;case"noCharacterController":Tail.Controller=null;break;case"wrongParent":G.Agents[1].Group=new SCR_AIGroup();break;case"wrongControl":Tail.Control.Agent=new AIAgent();break;case"noControl":Tail.Control=null;break;case"noAccess":Tail.Access=null;break;case"unconscious":Tail.Conscious=false;break;case"memberVehicle":Tail.InVehicle=true;break;case"inside":Tail.Access.Inside=true;break;case"gettingIn":Tail.Access.GettingIn=true;break;case"gettingOut":Tail.Access.GettingOut=true;break;case"switching":Tail.Access.Switching=true;break;case"attached":Tail.Access.Attached=new IEntity();break;case"noLiving":Leader.Alive=Tail.Alive=false;break;case"overflow":for(int i=0;i<10;i++)Add(10);break;}Reject(k);n++;}
foreach(string k in new[]{"group","generation","assignment","intent","waypoint","queueRemoved","target","pending","failed","utility","selected","executed","owner","origin","height","related"}){Setup();G.OnAgents=()=>{switch(k){case"group":S.Group=new SCR_AIGroup();break;case"generation":S.Generation+=2;break;case"assignment":S.Assignment+=2;break;case"intent":S.Intent+=2;break;case"waypoint":S.Waypoint=new SCR_DefendWaypoint();break;case"queueRemoved":G.Waypoints.Clear();break;case"target":S.Target=S.IntentTarget=new vector(2,0);break;case"pending":S.Pending=true;break;case"failed":S.Failed=true;break;case"utility":G.Utility=new SCR_AIGroupUtilityComponent();break;case"selected":G.Utility.Current=new SCR_AIMoveActivity();break;case"executed":G.Utility.Executed=new SCR_AIMoveActivity();break;case"owner":B.Owner=new IEntity();break;case"origin":B.Owner.Position=new vector(B.Owner.Position.X+1,0);break;case"height":B.Owner.Position.Y+=1;break;case"related":A.m_RelatedWaypoint=new SCR_DefendWaypoint();break;}};Reject("after native read/"+k);n++;}
Setup();if(Flow.Egress(S,B,false,false)||Flow.Egress(S,B,true,true))throw new Exception("existing outside/allowed exception changed");S.Target=S.IntentTarget=W.Position=new vector(101,0);if(!Flow.Egress(S,B,true,false))throw new Exception("new outward intent must require egress immediately");n++;
return n;}}
}
'@
$taskCompiled=$taskShim.Replace('FORMATION',(Replay (Body $taskArrival 'IsFormationAtWaypoint'))).Replace('FLOW',$taskFlow)+(Replay $taskPolicy)+$taskCases
Add-Type -TypeDefinition $taskCompiled -Language CSharp
$taskCount=[MobInternalReplay.Cases]::Run()
$taskMutants=@(
 @('authority','slot.GetDecisionAuthority() == AICF_EStrategicDecisionAuthority.PLAYER_COMMAND','ReplayGuard.On()'),
 @('pending','!slot.HasPendingOrderRecovery()','ReplayGuard.On()'),
 @('executed','utility.GetExecutedAction() == activity','ReplayGuard.On()'),
 @('running','activity.GetActionState() == EAIActionState.RUNNING','ReplayGuard.On()'),
 @('related','activity.m_RelatedWaypoint == waypoint','ReplayGuard.On()'),
 @('queue','!waypoints.Contains(waypoint)','ReplayGuard.Off()'),
 @('radius','vector.DistanceSqXZ(targetPosition, mobOrigin) > mobRadiusMeters * mobRadiusMeters','ReplayGuard.Off()'),
 @('foot','access.IsInCompartment()','ReplayGuard.Off()'),
 @('control','control.GetControlAIAgent() != agent','ReplayGuard.Off()'),
 @('generation','slot.GetSpawnGeneration() == generation','ReplayGuard.On()'),
 @('flow','atMob && !allowedException && !internalTask','atMob && !allowedException')
)
$taskCaught=0
foreach($taskMutation in $taskMutants){if(!$taskCompiled.Contains($taskMutation[1])){throw "Mutation target missing: $($taskMutation[0])"};$taskNS='MobInternalUnsafe'+$taskMutation[0];Add-Type -TypeDefinition ($taskCompiled.Replace('MobInternalReplay',$taskNS).Replace($taskMutation[1],$taskMutation[2])) -Language CSharp;$taskRejected=$false;try{[void]([type]($taskNS+'.Cases')).GetMethod('Run').Invoke($null,@())}catch{$taskRejected=$true};if(!$taskRejected){throw "Unsafe mutation survived: $($taskMutation[0])"};$taskCaught++}
"PASS player_mob_internal_task actual_predicate_flow_cases=$taskCount executed_unsafe=$taskCaught original_arrival_body_unchanged=1 stationary_outsider_is_not_arrival=1 native=NOT_RUN"
